const KEY='investor-research-desk-v2',OLD_KEY='investor-voice-radar-v1';
const $=id=>document.getElementById(id),clone=x=>structuredClone(x),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
