function plain(s){const d=new DOMParser().parseFromString(String(s||'').slice(0,30000),'text/html');d.querySelectorAll('script,style').forEach(x=>x.remove());return (d.body.textContent||'').replace(/\s+/g,' ').trim()}
function validDate(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d+'T12:00:00Z'))&&new Date(d+'T12:00:00Z').toISOString().startsWith(d)}
function normalizeV1(x){const base=clone(BUNDLED),ids=new Set(base.people.map(p=>p.id));base.timeline=[];for(const i of x.items||[]){if(!ids.has(i.person)||!i.id||!safeUrl(i.url))continue;base.timeline.push({id:String(i.id),rootId:String(i.id),person:i.person,title:String(i.title||'旧版记录'),summary:String(i.summary||''),url:safeUrl(i.url),source:String(i.source||'26人版迁移'),kind:i.seed?(i.person==='buffett'?'institution':'original'):i.kind==='holding'?'holding':i.manual?'opinion':'lead',evidenceLevel:i.seed?(i.person==='buffett'?'L4':'L3'):'L0',verification:i.seed?'source_checked':'pending',statementDate:null,publishedAt:i.date||null,recordedAt:i.seenAt||now(),dateOnly:!!i.dateOnly,topic:'未分类',target:'',horizon:'',stance:'unassigned',revisionOf:null,migrated:true})}base.favorites=(x.favorites||[]).filter(i=>ids.has(i));base.saved=x.saved||[];base.read=x.read||[];base.sources=[];for(const s of x.customFeeds||[])if(ids.has(s.person)&&safeUrl(s.url))base.sources.push({id:'legacy-rss-'+fnv(s.person+s.url),person:s.person,name:s.name||'旧版RSS',url:safeUrl(s.url),type:'rss',enabled:true,evidenceLevel:'L0',attribution:'unverified',status:'旧版迁移，待检查'});base.settings={...base.settings,...x.settings};return base}
function appendUnique(a,b,{conflict=false}={}){const known=new Map(a.map(x=>[x.id,x]));let n=0;for(const x of b){if(known.has(x.id)){if(conflict&&JSON.stringify(known.get(x.id))!==JSON.stringify(x)){const copy={...x,id:uid('import-revision'),revisionOf:x.id,recordedAt:now(),importConflict:true};a.push(copy);n++}continue}a.push(clone(x));known.set(x.id,x);n++}return n}
function mergeInto(s,x,{preferences=false,conflicts=false}={}){s.triage=s.triage||[];let added=appendUnique(s.timeline,x.timeline||[],{conflict:conflicts});appendUnique(s.assessments,x.assessments||[]);appendUnique(s.triage,x.triage||[]);for(const k of ['predictions','settlements','observations'])appendUnique(s.scorecard[k],x.scorecard?.[k]||[]);for(const p of x.people||[]){const mine=s.people.find(y=>y.id===p.id);if(mine){appendUnique(mine.facts,p.facts||[]);appendUnique(mine.conflicts,(p.conflicts||[]).filter(y=>y.id));if(!mine.birthDate&&p.birthDate){mine.birthDate=p.birthDate;mine.ageStatus=p.ageStatus}}}appendUnique(s.sources,x.sources||[]);for(const [id,status] of Object.entries(x.sourceStatuses||{})){if(!s.sourceStatuses[id]||(Date.parse(status.lastAttempt||'')||0)>(Date.parse(s.sourceStatuses[id].lastAttempt||'')||0))s.sourceStatuses[id]=status;}if(preferences){s.favorites=[...new Set([...s.favorites,...x.favorites||[]])];s.saved=[...new Set([...s.saved,...x.saved||[]])];s.read=[...new Set([...s.read,...x.read||[]])]}return added}
let hadStorage=false;
function loadStore(){const base=clone(BUNDLED);try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(x?.schema===2){hadStorage=true;const merged={...base,...x,settings:{...base.settings,...x.settings},scorecard:{...base.scorecard,...x.scorecard},triage:x.triage||[]};mergeInto(merged,base);return merged}const old=JSON.parse(localStorage.getItem(OLD_KEY)||'null');if(old?.schema===1){mergeInto(base,normalizeV1(old),{preferences:true});base.settings={...base.settings,...old.settings};if(Array.isArray(old.favorites))base.favorites=old.favorites.filter(id=>base.people.some(p=>p.id===id));base.migrationNote='已从26人版缓存迁移';hadStorage=true}}catch{}return base}
let state=loadStore(),selected='all',view='board',favOnly=false,limit=30,reviewLimit=30,busy=false,halted=false,timer=null,localDetected=false,csrf='',serverRevision=null,dirty=false,controllers=new Set();
if(['127.0.0.1','localhost'].includes(location.hostname)&&location.protocol==='http:')state.settings.localUrl=location.origin;
const pBy=id=>state.people.find(p=>p.id===id),byId=id=>state.timeline.find(x=>x.id===id),assessment=id=>state.assessments.filter(a=>a.itemId===id).at(-1);
const statusNames={pending:'待核验',source_checked:'出处已核查',verified:'用户已核验',disputed:'存在争议'},kindNames={draft:'原稿备忘',lead:'公开线索',opinion:'人工整理',original:'本人原始出处',holding:'持仓线索',institution:'机构披露'},stanceNames={unassigned:'未解码',bullish:'看多／上升',bearish:'看空／下降',neutral:'中性',conditional:'条件判断'};
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.handle);toast.handle=setTimeout(()=>$('toast').hidden=true,5000)}
function persist(mark=true){dirty=dirty||mark;try{localStorage.setItem(KEY,JSON.stringify(state));$('storeStatus').textContent=localDetected?(dirty?'浏览器有修改 · 可保存到JSON':'本地服务已连接'):'浏览器缓存 · 请定期备份'}catch{$('storeStatus').textContent='缓存保存失败 · 请立即导出备份';toast('浏览器缓存不足或不可用，历史未删除，请立即导出备份。')}}
function ageValue(p){if(p.birthDate&&validDate(p.birthDate)){const b=new Date(p.birthDate+'T12:00:00Z'),t=today();let n=Number(t.slice(0,4))-b.getUTCFullYear();if(t.slice(5)<p.birthDate.slice(5))n--;return n}return p.ageSnapshot}
function ageText(p){const a=ageValue(p);return a===null||a===undefined?(p.ageNote||'年龄未知'):`${p.ageApproximate?'约':''}${a}岁${p.birthDate?' · 用户核验':' · 原稿待核验'}`}
function matchPerson(p){if(selected!=='all'&&p.id!==selected)return false;if(favOnly&&!state.favorites.includes(p.id))return false;const group=$('groupFilter').value,market=$('marketFilter').value,domain=$('domainFilter').value,a=$('ageFilter').value,n=ageValue(p);if(group!=='all'&&p.originalGroup!==group)return false;if(market!=='all'&&!p.markets.includes(market))return false;if(domain!=='all'&&!p.domains.includes(domain))return false;if(a!=='all'){if(a==='unknown'&&n!=null)return false;if(a!=='unknown'&&n==null)return false;if(a==='80'&&n<80||a==='67'&&(n<67||n>=80)||a==='55'&&(n<55||n>=67)||a==='35'&&(n<35||n>=55)||a==='under'&&n>=35)return false}const q=$('search').value.trim().toLowerCase();return !q||`${p.name} ${p.en} ${p.specialty} ${p.domains.join(' ')}`.toLowerCase().includes(q)||state.timeline.some(x=>x.person===p.id&&`${x.title} ${x.summary} ${x.source} ${assessment(x.id)?.target||''}`.toLowerCase().includes(q))}
function currentRecords(){const superseded=new Set(state.timeline.map(x=>x.revisionOf).filter(Boolean));return state.timeline.filter(x=>!superseded.has(x.id))}
function verification(x){return assessment(x.id)?.verification||x.verification||'pending'}
function latestFor(person){const rows=currentRecords().filter(x=>x.person===person);const checked=rows.filter(x=>['verified','source_checked'].includes(verification(x)));return (checked.length?checked:rows).sort((a,b)=>Date.parse(b.statementDate||b.publishedAt||b.recordedAt)-Date.parse(a.statementDate||a.publishedAt||a.recordedAt))[0]}
function freshness(x){const d=x.statementDate||x.publishedAt;if(!d)return '表态日期待核验';const age=Math.max(0,Math.floor((Date.now()-Date.parse(d.length===10?d+'T12:00:00+08:00':d))/86400000));return `${age}天前${x.statementDate?'表态':'发布（表态日未知）'}`}
function renderStats(){ $('recordCount').textContent=state.timeline.length;$('recordCaption').textContent=`${currentRecords().length}条当前记录 · 历史版本保留`;$('favCount').textContent=state.favorites.length;$('predictionCount').textContent=state.scorecard.predictions.length;const confirmed=state.scorecard.predictions.filter(p=>lastSettlement(p.id)?.status==='confirmed').length;$('predictionCaption').textContent=`已复核结算 ${confirmed}条`;const last=Object.values(state.sourceStatuses).map(x=>x.lastSuccess).filter(Boolean).sort().at(-1);$('lastUpdate').textContent=last?fmt(last):'尚未更新'}
function renderPeople(){let html=`<div class="person"><button class="select-person ${selected==='all'?'active':''}" data-person="all">全部41人</button></div>`;for(const group of ['A','B','C','D','E','F','G']){const rows=state.people.filter(p=>p.originalGroup===group&&(!favOnly||state.favorites.includes(p.id)));if(!rows.length)continue;html+=`<details open><summary>${group} · 原稿分组 / ${rows.length}人</summary>`;for(const p of rows)html+=`<div class="person"><button data-star="${p.id}" class="star ${state.favorites.includes(p.id)?'on':''}" aria-label="${state.favorites.includes(p.id)?'取消关注':'关注'}${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'★':'☆'}</button><button class="select-person ${selected===p.id?'active':''}" data-person="${p.id}">${esc(p.name)}</button></div>`;html+='</details>'}$('people').innerHTML=html;$('mobilePerson').innerHTML='<option value="all">全部41人</option>'+state.people.map(p=>`<option value="${p.id}">${state.favorites.includes(p.id)?'★ ':''}${esc(p.name)}</option>`).join('');$('mobilePerson').value=selected;$('onlyFav').textContent=favOnly?'显示全部':'只看关注'}
function renderBoard(){const people=state.people.filter(matchPerson);$('boardTitle').textContent=`${selected==='all'?'人物看板':pBy(selected)?.name} · ${people.length}人`;$('boardCards').innerHTML=people.map(p=>{const x=latestFor(p.id),v=x?verification(x):'pending';return `<article class="person-card"><div class="section-top" style="margin-bottom:3px"><h3>${esc(p.name)}</h3><button class="quiet" data-star="${p.id}" aria-label="关注${esc(p.name)}">${state.favorites.includes(p.id)?'★':'☆'}</button></div><span class="small">${esc(ageText(p))} · 原稿${p.originalGroup}</span><div class="badges">${p.markets.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}${p.domains.slice(0,3).map(t=>`<span class="pill media">${esc(t)}</span>`).join('')}</div><div class="small">最新${['source_checked','verified'].includes(v)?'已核查出处记录':'原稿／公开线索'}</div><p class="quote">${esc(x?.summary||'暂未收录观点')}</p><div class="badges"><span class="pill ${v==='pending'?'pending':'original'}">${esc(assessment(x?.id)?.evidenceLevel||x?.evidenceLevel||'L0')} · ${esc(statusNames[v])}</span><span class="pill pending">利益关联${p.conflicts.some(c=>c.status==='verified')?'有核验记录':'待核验'}</span><span class="pill">${esc(x?freshness(x):'无记录')}</span></div><div class="actions"><button data-details="${p.id}">档案／核验</button><button data-timeline="${p.id}">观点演进</button>${x?`<button data-process="${esc(x.id)}">处理观点</button>`:''}</div></article>`}).join('')||'<div class="empty">没有匹配人物，请调整筛选。</div>'}
function timelineTime(x){return Date.parse(x.statementDate||x.publishedAt||(x.kind==='draft'?'1970-01-01':x.recordedAt))||0}
function filteredRecords(){const allowed=new Set(state.people.filter(matchPerson).map(p=>p.id)),q=$('search').value.trim().toLowerCase(),period=$('period').value,kind=$('kindFilter').value;const rows=$('versionFilter').value==='all'?state.timeline:currentRecords();return rows.filter(x=>{if(!allowed.has(x.person))return false;if(q&&!`${pBy(x.person)?.name} ${x.title} ${x.summary} ${x.source} ${assessment(x.id)?.target||''}`.toLowerCase().includes(q))return false;const d=x.statementDate||x.publishedAt;if(period==='2026'&&(!d||new Date(d).getFullYear()!==2026))return false;if(['30','90'].includes(period)&&(!d||Date.now()-Date.parse(d)>Number(period)*86400000))return false;if(kind==='checked'&&!['verified','source_checked'].includes(verification(x)))return false;if(kind==='saved'&&!state.saved.includes(x.id))return false;if(kind==='unread'&&state.read.includes(x.id))return false;if(!['all','checked','saved','unread'].includes(kind)&&kind!==x.kind)return false;return true}).sort((a,b)=>timelineTime(b)-timelineTime(a))}
function textDiff(a,b){let i=0,j=0;while(i<Math.min(a.length,b.length)&&a[i]===b[i])i++;while(j<Math.min(a.length-i,b.length-i)&&a[a.length-1-j]===b[b.length-1-j])j++;return `<div>原：${esc(a.slice(0,i))}<del>${esc(a.slice(i,a.length-j))}</del>${esc(j?a.slice(-j):'')}</div><div>新：${esc(b.slice(0,i))}<ins>${esc(b.slice(i,b.length-j))}</ins>${esc(j?b.slice(-j):'')}</div>`}
function score(x,a){if(!a||a.verification!=='verified'||!safeUrl(x.url))return {value:null,reason:'原文与上下文未核验，暂不评分'};const d=x.statementDate||x.publishedAt;if(!d)return{value:null,reason:'日期待核验，无法计算新鲜度'};const weights={L0:20,L1:45,L2:70,L3:85,L4:100},m={direct:1,partial:.5,none:0},f={clear:1,partial:.6,vague:.2};const days=Math.max(0,(Date.now()-Date.parse(d))/86400000),fresh=Math.pow(.5,days/Number(a.halfLife||90));const hold=a.holdings==='divergent'?.65:1;const n=Math.round((weights[a.evidenceLevel]||20)*(m[a.match]??0)*(f[a.falsifiability]??.2)*hold*fresh);return{value:n,reason:`出处基值 ${weights[a.evidenceLevel]} × 匹配 ${m[a.match]} × 可检验 ${f[a.falsifiability]} × 仓位因素 ${hold} × 新鲜度 ${fresh.toFixed(2)}；${a.holdings==='unknown'?'仓位未知不判为背离。':''}独立证据另列，不按共识人数加分。`}}
function priorComparable(x,a){if(!a?.target||!a?.horizon)return null;return state.timeline.filter(y=>y.person===x.person&&y.id!==x.id&&Date.parse(y.statementDate||y.publishedAt||y.recordedAt)<Date.parse(x.statementDate||x.publishedAt||x.recordedAt)).map(y=>({x:y,a:assessment(y.id)})).filter(y=>y.a?.target===a.target&&y.a?.horizon===a.horizon&&y.a?.topic===a.topic).sort((a,b)=>timelineTime(b.x)-timelineTime(a.x))[0]}
function renderTimeline(){const rows=filteredRecords();$('timelineTitle').textContent=(selected==='all'?'观点时间轴':pBy(selected)?.name)+` · ${rows.length}条`;$('refreshSelected').hidden=selected==='all';$('feed').innerHTML=rows.slice(0,limit).map(x=>{const a=assessment(x.id),v=verification(x),old=x.revisionOf?byId(x.revisionOf):null,prev=priorComparable(x,a),s=score(x,a);return `<article class="entry ${state.read.includes(x.id)?'read':''}"><div class="meta"><strong>${esc(pBy(x.person)?.name)}</strong><span class="pill ${v==='pending'?'pending':'original'}">${esc(a?.evidenceLevel||x.evidenceLevel)} · ${esc(statusNames[v])}</span><span class="pill">${esc(kindNames[x.kind]||'记录')}</span><time>${esc(freshness(x))}</time></div><h3>${link(x.url,x.title)}</h3><p>${esc(x.summary)}</p><div class="small">本人表态：${esc(fmt(x.statementDate,true))} · 来源发布：${esc(fmt(x.publishedAt,!!x.dateOnly))}${x.reportDate?' · 报告期 '+esc(x.reportDate):''}<br>收录：${esc(fmt(x.recordedAt))} · ${esc(x.source)}</div>${a?`<div class="assessment">研究判断：${esc(stanceNames[a.stance])} · ${esc(a.target||'标的未填')} · ${esc(a.horizon||'期限未填')}<br>${esc(a.interpretation||'')}<br>研究参考评分：${s.value===null?'信息不足':s.value+' / 100'} · ${esc(s.reason)}</div>`:''}${old?`<details class="history"><summary>修订版本 · 原记录保留</summary>${textDiff(old.summary,x.summary)}</details>`:''}${prev?`<details class="history"><summary>${esc(stanceNames[prev.a.stance])} → ${esc(stanceNames[a.stance])} · 同主题／标的／期限，条件仍需人工比较</summary>${textDiff(prev.a.interpretation||prev.x.summary,a.interpretation||x.summary)}</details>`:''}<div class="foot" style="margin-top:14px"><span>${link(x.url,'打开出处')}</span><span><button data-save="${esc(x.id)}">${state.saved.includes(x.id)?'★ 已收藏':'☆ 收藏'}</button> <button data-read="${esc(x.id)}">${state.read.includes(x.id)?'设未读':'标已读'}</button> <button data-process="${esc(x.id)}">五步处理</button> <button data-edit="${esc(x.id)}">追加修订</button></span></div></article>`}).join('')||'<div class="empty">当前筛选下暂无记录。未知日期的原稿只在全部记录中显示。</div>';$('more').hidden=rows.length<=limit}
function renderSources(){const ids=new Set(state.people.filter(matchPerson).map(p=>p.id));$('sourceCards').innerHTML=state.sources.filter(s=>ids.has(s.person)).map(s=>{const st=state.sourceStatuses[s.id],manual=s.type==='manual';return `<article class="source-card"><h3>${esc(pBy(s.person)?.name)} · ${esc(s.name)}</h3><div class="badges"><span class="pill">${esc({manual:'人工入口',rss:'RSS / Atom',news:'报道发现',edgar:'机构备案'}[s.type])}</span><span class="pill ${s.enabled?'original':'pending'}">${manual?'人工阅读':s.enabled?'已启用':'未启用'}</span></div><p>${link(s.url,s.url)}</p><div class="source-status">${esc(s.status||'待检查')}${st?'<br>'+esc(st.ok?`最近成功 ${fmt(st.lastSuccess)} · ${st.count||0}条 / 新增${st.added||0}条`:`失败 ${st.error} · 上次成功 ${fmt(st.lastSuccess)}`):''}</div><div class="actions">${!manual?`<button data-source-toggle="${esc(s.id)}">${s.enabled?'暂停采集':'启用采集'}</button><button data-source-fetch="${esc(s.id)}">检查／获取</button>`:''}</div></article>`}).join('')}
function showPerson(id){const p=pBy(id);$('personDialogName').textContent=p.name;$('factPerson').value=id;$('factForm').reset();$('factPerson').value=id;$('personDialogBody').innerHTML=`<p class="small">${esc(p.en)} · ${esc(ageText(p))} · 主战场 ${esc(p.markets.join('／')||'不作标的建议')}</p><p class="facts">${esc(p.specialty)}</p><ul class="facts">${p.facts.map(f=>`<li>${esc(f.text)} <span class="pill ${f.status==='verified'?'original':'pending'}">${esc(f.status==='verified'?'用户已核验':f.status)}</span> ${link(f.url,'出处')}</li>`).join('')}</ul><div class="notice">利益关联：${p.conflicts.map(c=>esc(c.detail)).join('；')}<br>无公开记录不等于无利益关联。</div><div class="actions">${p.links.map(([t,u])=>link(u,t)).join(' ')}</div>`;$('personDialog').showModal()}
