function itemOptions(person=null){return currentRecords().filter(x=>!person||x.person===person).map(x=>`<option value="${esc(x.id)}">${esc(pBy(x.person)?.name)} · ${esc(x.title.slice(0,90))}</option>`).join('')}
function openOpinion(id=null){$('opinionForm').reset();$('editId').value=id||'';$('oPerson').disabled=!!id;if(id){const x=byId(id);$('oPerson').value=x.person;$('oKind').value=['opinion','lead','holding','institution'].includes(x.kind)?x.kind:'opinion';$('oTitle').value=x.title;$('oSummary').value=x.summary;$('oUrl').value=x.url||'';$('oStatement').value=x.statementDate||'';$('oPublished').value=x.publishedAt?.slice(0,10)||'';$('oLevel').value=x.evidenceLevel;$('oVerification').value=['verified','disputed'].includes(verification(x))?verification(x):'pending'}else{$('oPerson').value=selected==='all'?state.people[0].id:selected;$('oPublished').value=today()}$('opinionDialogTitle').textContent=id?'追加修订版本（原文保留）':'录入观点';$('opinionDialog').showModal()}
function renderProcessChoices(){const id=$('processItem').value;$('processItem').innerHTML=itemOptions(selected==='all'?null:selected);if(byId(id))$('processItem').value=id;loadAssessment()}
function loadAssessment(){const x=byId($('processItem').value);if(!x)return;const a=assessment(x.id)||{};$('processPreview').innerHTML=`<p><strong>${esc(x.title)}</strong><br>${esc(x.summary)}</p><p class="small">${link(x.url,'原始出处')} · ${esc(freshness(x))} · 已保存评估 ${state.assessments.filter(y=>y.itemId===x.id).length}版</p>`;const map={aVerification:a.verification||x.verification,aLevel:a.evidenceLevel||x.evidenceLevel,aMatch:a.match||'direct',aFalsifiable:a.falsifiability||'vague',aTarget:a.target||x.target||'',aHorizon:a.horizon||x.horizon||'',aStance:a.stance||x.stance||'unassigned',aTopic:a.topic||x.topic||'',aInterpretation:a.interpretation||'',aHoldings:a.holdings||'unknown',aHoldingsDate:a.holdingsDate||'',aHoldingsUrl:a.holdingsUrl||'',aHalfLife:a.halfLife||90,aCross:a.crossCount||0,aCrossUrls:(a.crossUrls||[]).join('\n'),aPersonal:a.personal||'uncertain',aNews:a.dimensions?.news||0,aTechnical:a.dimensions?.technical||0,aSentiment:a.dimensions?.sentiment||0,aMarket:a.dimensions?.market||0};for(const [id,value] of Object.entries(map))$(id).value=id==='aVerification'&&value==='source_checked'?'pending':value;renderScorePreview()}
function getAssessment(){return{itemId:$('processItem').value,verification:$('aVerification').value,evidenceLevel:$('aLevel').value,match:$('aMatch').value,falsifiability:$('aFalsifiable').value,target:$('aTarget').value.trim(),horizon:$('aHorizon').value.trim(),stance:$('aStance').value,topic:$('aTopic').value.trim(),interpretation:$('aInterpretation').value.trim(),holdings:$('aHoldings').value,holdingsDate:$('aHoldingsDate').value||null,holdingsUrl:safeUrl($('aHoldingsUrl').value)||null,halfLife:Number($('aHalfLife').value),crossCount:Number($('aCross').value),crossUrls:$('aCrossUrls').value.split('\n').map(x=>safeUrl(x.trim())).filter(Boolean),personal:$('aPersonal').value,dimensions:{news:Number($('aNews').value),technical:Number($('aTechnical').value),sentiment:Number($('aSentiment').value),market:Number($('aMarket').value)}}}
function renderScorePreview(){const x=byId($('processItem').value);if(!x)return;const s=score(x,getAssessment());$('scorePreview').innerHTML=`<strong>研究参考评分：${s.value===null?'信息不足':s.value+' / 100'}</strong><br>${esc(s.reason)}<br><span class="small">参数是可调整的研究规则，未校准为正确概率或预期收益。≥70进入研究队列；＜50保留档案。</span>`}
function openProcess(id){setView('process');$('processItem').value=id;loadAssessment();scrollTo({top:$('process').offsetTop-15,behavior:'smooth'})}
function trial(pred,asOf=today()){if(asOf<pred.dueDate)return{status:'not_due',reason:'尚未到期'};const lo=new Date(pred.dueDate+'T12:00:00Z');lo.setUTCDate(lo.getUTCDate()-7);const min=lo.toISOString().slice(0,10),r=pred.rule;const obs=state.scorecard.observations.filter(x=>x.symbol===pred.symbol&&x.currency===pred.currency&&x.adjustment===r.adjustment&&x.date>=min&&x.date<=pred.dueDate).sort((a,b)=>b.date.localeCompare(a.date)||b.recordedAt.localeCompare(a.recordedAt))[0];if(!obs)return{status:'missing_data',reason:'缺少同币种、同口径且到期日前7天内的结果数据'};let value=Number(obs.value);if(r.operator.startsWith('return_')){if(!(r.baseline>0))return{status:'missing_data',reason:'缺少有效基准值'};value=(value/r.baseline-1)*100}return{status:'proposed',hit:r.operator.endsWith('gte')?value>=r.threshold:value<=r.threshold,value,observationId:obs.id,observationDate:obs.date,sourceUrl:obs.sourceUrl,reason:'按登记规则试算，待复核'}}
function lastSettlement(id){return state.scorecard.settlements.filter(s=>s.predictionId===id).at(-1)}
function horizonBucket(p){const days=(Date.parse(p.dueDate)-Date.parse(p.registeredAt))/86400000;return days<=90?'short':days<=365?'medium':'long'}
function wilson(h,n){if(!n)return[0,1];const z=1.96,p=h/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,m=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return[c-m,c+m]}
function rankingRows(domain,bucket){if(domain==='all'||bucket==='all')return[];const result=[];for(const p of state.people){const rows=state.scorecard.predictions.filter(x=>x.person===p.id&&x.domain===domain&&horizonBucket(x)===bucket&&!x.retrospective);const outcomes=rows.map(x=>lastSettlement(x.id)).filter(x=>x?.status==='confirmed'),hits=outcomes.filter(x=>x.hit).length,n=outcomes.length;if(n){const interval=wilson(hits,n);result.push({person:p.name,n,hits,rate:hits/n,interval,eligible:n>=Number(state.settings.rankMinimum||20)})}}return result.sort((a,b)=>Number(b.eligible)-Number(a.eligible)||b.rate-a.rate)}
function renderPredictions(){const oldDomain=$('rankDomain').value,domains=[...new Set(state.scorecard.predictions.map(x=>x.domain))];$('rankDomain').innerHTML='<option value="all">全部领域（不混合排名）</option>'+domains.map(x=>`<option>${esc(x)}</option>`).join('');if(domains.includes(oldDomain))$('rankDomain').value=oldDomain;const rank=rankingRows($('rankDomain').value,$('rankHorizon').value);$('ranking').innerHTML=rank.length?`<div class="box table-wrap"><table class="table"><thead><tr><th>人物</th><th>已结算样本</th><th>命中率</th><th>95%区间</th><th>排名资格</th></tr></thead><tbody>${rank.map(x=>`<tr><td>${esc(x.person)}</td><td>${x.hits}/${x.n}</td><td>${(100*x.rate).toFixed(1)}%</td><td>${(100*x.interval[0]).toFixed(1)}–${(100*x.interval[1]).toFixed(1)}%</td><td>${x.eligible?'可进入此领域／期限排名':'样本不足，暂不排名'}</td></tr>`).join('')}</tbody></table><p>命中率不等于投资收益；不同规则难度仍需逐条比较。历史补录不进入前瞻排名。</p></div>`:'<div class="empty" style="margin-top:16px">选择同一领域和期限后比较；没有合格样本时不制造排名。</div>';const ids=new Set(state.people.filter(matchPerson).map(p=>p.id));$('forecastList').innerHTML=state.scorecard.predictions.filter(p=>ids.has(p.person)).map(p=>{const end=lastSettlement(p.id),r=end?.status==='confirmed'?`已复核：${end.hit?'命中':'未命中'}`:end?.status==='unresolvable'?'无法结算':trial(p).status==='not_due'?'未到期':trial(p).status==='missing_data'?'到期缺数据':'待复核';return `<article class="forecast"><div class="section-top"><h3>${esc(pBy(p.person)?.name)} · ${esc(p.symbol)}</h3><span class="pill ${end?.status==='confirmed'?'original':'pending'}">${r}</span></div><p>${esc(p.claim)}</p><div class="small">领域 ${esc(p.domain)} · 到期 ${esc(p.dueDate)} · ${esc(p.currency)} · ${p.rule.operator.startsWith('return_')?'变化率':'结果值'} ${p.rule.operator.endsWith('gte')?'≥':'≤'} ${p.rule.threshold}${p.rule.operator.startsWith('return_')?'%':''}<br>登记 ${esc(fmt(p.registeredAt))} · ${p.attribution==='author'?'作者明确承诺（用户核验）':'研究者操作化定义'}${p.retrospective?' · 历史补录，排除前瞻排名':''}</div>${end?`<p class="small">${esc(end.note||end.reason||'')} ${link(end.sourceUrl,'结果出处')}</p>`:''}<div class="actions">${link(p.evidenceUrl,'预测依据')}<button data-result="${esc(p.id)}">查看／复核结果</button></div></article>`}).join('')||'<div class="empty" style="margin-top:16px">尚未登记可检验预测。原稿中的模糊观点不会自动变成作者的量化承诺。</div>'}
function predictionChoices(){const person=$('pPerson').value;$('pOpinion').innerHTML='<option value="">研究者自行登记（不归为本人原话）</option>'+itemOptions(person)}
function openPrediction(itemId=null){$('predictionForm').reset();const x=itemId?byId(itemId):null,a=x?assessment(x.id):null;$('pPerson').value=x?.person||(selected==='all'?state.people[0].id:selected);predictionChoices();if(x){$('pOpinion').value=x.id;$('pClaim').value=a?.interpretation||x.summary;$('pDomain').value=a?.topic||x.topic||'';$('pEvidenceUrl').value=x.url||''}$('pDue').value='';$('predictionDialog').showModal()}
function openResult(id){const p=state.scorecard.predictions.find(x=>x.id===id),t=trial(p);$('resultPrediction').value=id;$('resultNote').value='';$('resultDetails').innerHTML=`<p>${esc(pBy(p.person)?.name)} · ${esc(p.claim)}</p><div class="score-output">${esc(t.reason)}${t.status==='proposed'?`<br>结果值 ${t.value.toFixed(4)} · ${t.hit?'命中':'未命中'}<br>观察日期 ${esc(t.observationDate)} · ${link(t.sourceUrl,'结果来源')}`:''}</div><p class="small">币种、复权／指标口径及结算日期须一致。确认会追加结算版本，不修改登记规则。</p>`;$('resultForm').querySelector('[type=submit]').disabled=t.status!=='proposed';$('resultDialog').showModal()}
function renderSettingsExtras(){ $('statusList').innerHTML=state.sources.filter(s=>s.type!=='manual').map(s=>{const st=state.sourceStatuses[s.id];return `<div class="status-row"><strong>${esc(pBy(s.person)?.name)} · ${esc(s.name)}</strong><span class="${st?.ok?'ok':st?'error':'small'}">${st?esc(st.ok?`成功 ${fmt(st.lastSuccess)} · ${st.count||0}条 / 新增${st.added||0}`:st.error+' · 上次成功 '+fmt(st.lastSuccess)):s.enabled?'未获取':'未启用'}</span></div>`}).join('');$('priceSources').innerHTML=(state.settings.priceSources||[]).map((s,i)=>`<div class="status-row"><span>${esc(s.name)} · ${link(s.url,'CSV来源')}</span><button data-price-toggle="${i}">${s.enabled?'暂停':'启用'}</button></div>`).join('')}
function loadSettings(){for(const k of ['mode','interval','localUrl','relayUrl','secUserAgent','rankMinimum'])$(k).value=state.settings[k]??'';$('autoStart').checked=!!state.settings.autoStart}
async function request(url,{timeout=22000,method='GET',body=null}={}){const c=new AbortController();controllers.add(c);const t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{method,body:body===null?null:JSON.stringify(body),headers:body===null?{}:{'Content-Type':'application/json','X-Radar-Token':csrf},signal:c.signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'});const text=await r.text();if(!r.ok){let msg='';try{msg=JSON.parse(text).error||''}catch{}throw Error(`HTTP ${r.status}${msg?' · '+msg:''}`)}if(text.length>25*1024*1024)throw Error('响应超过25MB');return text}catch(e){throw Error(e.name==='AbortError'?'请求超时或已停止':e.message)}finally{clearTimeout(t);controllers.delete(c)}}
function localBase(){const raw=state.settings.localUrl.replace(/\/+$/,'');const u=new URL(raw);if(!['127.0.0.1','localhost','[::1]'].includes(u.hostname)||!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('本地服务地址必须为localhost或127.0.0.1');return raw}
async function detectLocal(){try{const d=JSON.parse(await request(localBase()+'/api/health',{timeout:2000}));localDetected=d.service==='investor-radar'&&d.version==='2.0';csrf=d.token||'';return localDetected}catch{localDetected=false;return false}}
async function syncFiles(){if(!localDetected&&!await detectLocal())throw Error('未连接2.0本地服务，请运行完整包的启动脚本');const remote=validateBackup(JSON.parse(await request(localBase()+'/api/state')));const n=mergeInto(state,remote);if(!hadStorage&&!dirty){state.settings=remote.settings;state.favorites=remote.favorites;state.saved=remote.saved;state.read=remote.read;loadSettings()}serverRevision=remote.revision;state.revision=remote.revision;persist(false);render();return n}
async function saveFiles(){if(!localDetected&&!await detectLocal())throw Error('未连接本地服务；双击模式请导出JSON备份');if(serverRevision===null)await syncFiles();const out=JSON.parse(await request(localBase()+'/api/state',{method:'POST',body:{expectedRevision:serverRevision,state},timeout:20000}));serverRevision=out.revision;state.revision=out.revision;dirty=false;persist(false);toast('本地JSON已保存，历史版本保留。')}
async function loadSource(s){if(s.type==='edgar'){if(!localDetected)throw Error('EDGAR需要2.0本地服务、主体映射和真实User-Agent');const payload=JSON.parse(await request(localBase()+'/api/source',{method:'POST',body:{source:s,userAgent:state.settings.secUserAgent},timeout:24000}));if(!payload.status.ok)throw Error(payload.status.error);return{records:payload.records,via:'本地EDGAR'}}const mode=state.settings.mode;if(mode==='offline')throw Error('离线模式');if(mode==='local'||mode==='auto'&&localDetected){try{return {text:await request(localBase()+'/api/feed?'+new URLSearchParams({url:s.url}),{timeout:24000}),via:'本地服务'}}catch(e){if(mode==='local'||halted)throw e}}if(mode==='direct')return{text:await request(s.url),via:'直接连接'};const tmpl=state.settings.relayUrl;if(!tmpl.startsWith('https://')||!tmpl.includes('{url}'))throw Error('中转模板需为HTTPS并包含{url}');return{text:await request(tmpl.replaceAll('{url}',encodeURIComponent(s.url))),via:'公开RSS中转'}}
function parseFeed(text,s){if(/^\s*\{/.test(text)){const d=JSON.parse(text);if(d.status!=='ok'||!Array.isArray(d.items))throw Error(d.message||'中转未返回RSS数据');const rows=d.items.map(i=>`<item><title>${esc(i.title)}</title><link>${esc(i.link)}</link><pubDate>${esc(i.pubDate?(Number.isFinite(Date.parse(i.pubDate))?new Date(/[zZ]|[+-]\d{2}:?\d{2}$/.test(i.pubDate)?i.pubDate:i.pubDate.replace(' ','T')+'Z').toISOString():''):'')}</pubDate><description>${esc(i.description||i.content||'')}</description><author>${esc(i.author||'')}</author></item>`).join('');return parseFeed('<rss><channel>'+rows+'</channel></rss>',s)}if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('RSS含不支持的DTD声明');const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror')||!['rss','feed','RDF'].includes(xml.documentElement.localName))throw Error('来源未返回有效RSS / Atom');const records=[];for(const n of xml.querySelectorAll('item,entry')){const f=(...names)=>{for(const name of names){const c=[...n.children].find(x=>x.localName===name);if(c)return c.textContent.trim()}return ''};const title=plain(f('title')),ln=[...n.children].find(x=>x.localName==='link'&&['','alternate'].includes(x.getAttribute('rel')||'')),url=safeUrl(ln?.getAttribute('href')||ln?.textContent||f('guid'));if(!title||!url)continue;const author=plain(f('creator','author'));if(s.authorFilter&&(!author||!author.toLowerCase().includes(s.authorFilter.toLowerCase())))continue;const raw=f('pubDate','published','updated','date'),pub=raw&&Number.isFinite(Date.parse(raw))?new Date(raw).toISOString():null;const desc=plain(f('description','summary','encoded','content')).slice(0,1800),holding=/\b13[FDG]\b|holdings|持仓|增持|减持|清仓/i.test(title);const x={person:s.person,sourceId:s.id,title,summary:desc?(s.type==='news'?'公开报道摘要：':'订阅摘要：')+desc:'来源未提供摘要，请阅读原文及上下文。',url,source:f('source')||s.name,kind:s.attribution==='institution'?'institution':holding?'holding':'lead',evidenceLevel:s.evidenceLevel||'L0',verification:'pending',statementDate:null,publishedAt:pub,recordedAt:now(),author,topic:'未分类',target:'',horizon:'',stance:'unassigned',revisionOf:null};x.rootId=s.id+'-'+fnv(url);x.id=x.rootId+'-'+fingerprint(x);records.push(x);if(records.length>=100)break}return records}
function ingest(records){const known=new Set(state.timeline.map(x=>x.rootId+'|'+fingerprint(x)));let added=0;for(const x of records){const key=x.rootId+'|'+fingerprint(x);if(known.has(key))continue;const old=state.timeline.filter(y=>y.rootId===x.rootId).at(-1);if(old)x.revisionOf=old.id;if(state.timeline.some(y=>y.id===x.id))x.id=uid('revision');state.timeline.push(x);known.add(key);added++}return added}
async function refresh(ids,sourceIds=null){if(busy)return toast('正在更新，请等待或停止。');if(state.settings.mode==='offline')return toast('当前为离线模式。');let sources=state.sources.filter(s=>s.type!=='manual'&&(sourceIds?sourceIds.includes(s.id):s.enabled&&ids.includes(s.person)));if(!sources.length)return toast('没有启用的自动来源，可在来源目录添加或启用。');busy=true;halted=false;$('stop').hidden=false;['refreshFav','refreshAll','refreshSelected'].forEach(k=>$(k).disabled=true);$('bar').style.width='0%';$('status').textContent='检测连接…';if(['auto','local'].includes(state.settings.mode))await detectLocal();let next=0,done=0,success=0,added=0;
async function worker(){while(next<sources.length&&!halted){const s=sources[next++],prev=state.sourceStatuses[s.id]||{},attempt=now();$('status').textContent=`正在获取 ${pBy(s.person)?.name} · ${s.name}，${done}/${sources.length}`;try{const data=await loadSource(s);if(halted)break;const rows=data.records||parseFeed(data.text,s),n=ingest(rows);state.sourceStatuses[s.id]={...prev,ok:true,lastAttempt:attempt,lastSuccess:now(),count:rows.length,added:n,error:null};success++;added+=n}catch(e){if(halted)break;state.sourceStatuses[s.id]={...prev,ok:false,lastAttempt:attempt,error:e.message}}done++;$('bar').style.width=(done/sources.length*100)+'%';persist();render();$('status').textContent=`完成${done}/${sources.length}个来源，成功${success}个，新增${added}条。`}}
try{await Promise.all(Array.from({length:Math.min(3,sources.length)},worker));$('connection').textContent=halted?'更新已停止':success?'已连接 · '+(localDetected?'本地服务':'公开中转'):'获取失败 · 保留旧档案';$('status').textContent=halted?'已停止，已完成的记录保留。':`完成：${success}/${sources.length}来源成功，新增${added}条。失败详情在来源目录／更新与备份。${localDetected?'新记录暂存在浏览器，可保存到JSON。':''}`}finally{busy=false;$('stop').hidden=true;['refreshFav','refreshAll','refreshSelected'].forEach(k=>$(k).disabled=false);render()}}
function schedule(){clearInterval(timer);const minutes=Number(state.settings.interval);if(minutes>0)timer=setInterval(()=>{if(!busy&&!document.hidden&&state.settings.mode!=='offline')refresh(state.favorites)},minutes*60000)}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function csvEncode(rows){const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};return '\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')}
function csvParse(text){const rows=[];let row=[],cell='',quoted=false;text=text.replace(/^\ufeff/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV引号未闭合');if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function observationKey(x){return JSON.stringify([x.symbol.trim().toUpperCase(),x.date,Number(x.value),x.currency.trim().toUpperCase(),x.adjustment||'source_close',x.sourceUrl])}
function mergeObservations(existing,incoming){const known=new Set(existing.map(observationKey));let added=0;for(let x of incoming){const key=observationKey(x);if(known.has(key))continue;if(existing.some(y=>y.id===x.id))x={...x,id:uid('obs')};existing.push(clone(x));known.add(key);added++}return added}
function parsePrices(text){const rows=csvParse(text),header=rows.shift()||[],required=['symbol','date','value','currency','sourceUrl'];if(!required.every(k=>header.includes(k)))throw Error('CSV缺少symbol,date,value,currency,sourceUrl列');return rows.map(row=>{const r=Object.fromEntries(header.map((k,i)=>[k,row[i]||''])),value=Number(r.value),url=safeUrl(r.sourceUrl.trim()),symbol=r.symbol.trim().toUpperCase(),currency=r.currency.trim().toUpperCase(),adjustment=r.adjustment?.trim()||'source_close';if(!r.value.trim()||!Number.isFinite(value)||!validDate(r.date)||r.date>today()||!url||!symbol||!currency)throw Error('CSV含无效值、日期、单位或出处');return{id:'obs-'+fnv([symbol,r.date,String(value),currency,adjustment,url].join('|')),symbol,date:r.date,value,currency,sourceUrl:url,recordedAt:now(),adjustment}})}
function validateBackup(x){if(x?.schema===1)return normalizeV1(x);if(x?.schema!==2||!Array.isArray(x.timeline)||x.timeline.length>100000)throw Error('不是有效的研究台备份');const ids=new Set(BUNDLED.people.map(p=>p.id));x.timeline=x.timeline.filter(i=>ids.has(i.person)&&typeof i.id==='string'&&typeof i.title==='string'&&typeof i.summary==='string'&&(!i.url||safeUrl(i.url))).map(i=>({...i,title:i.title.slice(0,2000),summary:i.summary.slice(0,30000),url:i.url?safeUrl(i.url):null}));for(const k of ['assessments','people','sources','triage'])if(!Array.isArray(x[k]))x[k]=[];x.sources=x.sources.filter(s=>ids.has(s.person)&&['news','rss','manual','edgar'].includes(s.type)&&safeUrl(s.url));x.scorecard=x.scorecard||{};for(const k of ['predictions','settlements','observations'])if(!Array.isArray(x.scorecard[k]))x.scorecard[k]=[];x.scorecard.predictions=x.scorecard.predictions.filter(p=>ids.has(p.person)&&validDate(p.dueDate)&&p.rule&&['gte','lte','return_gte','return_lte'].includes(p.rule.operator)&&Number.isFinite(p.rule.threshold));return x}
