function localDay(d){if(!d)return null;if(validDate(d))return d;const n=Date.parse(d);return Number.isFinite(n)?DATE_DAY.format(new Date(n)):null}
function latestTriage(id){return(state.triage||[]).filter(t=>t.itemId===id).at(-1)}
function needsReview(x){return['pending','disputed'].includes(verification(x))&&!['irrelevant','duplicate'].includes(latestTriage(x.id)?.status)}
function reviewPriority(x){return(state.favorites.includes(x.person)?100:0)+(verification(x)==='disputed'?40:0)+(/任职|出任|巨额|崩塌|爆仓|清仓|亿元|十亿美元|CFO|CEO|billion|collapse|bankrupt/i.test(x.title+' '+x.summary)?30:0)+(['holding','institution'].includes(x.kind)?20:0)}
function reviewRows(){const scope=new Set(state.people.filter(matchPerson).map(p=>p.id)),mode=$('reviewStatus').value;return currentRecords().filter(x=>scope.has(x.person)&&(!$('reviewFav').checked||state.favorites.includes(x.person))&&(mode==='excluded'?['irrelevant','duplicate'].includes(latestTriage(x.id)?.status):mode==='followup'?needsReview(x)&&latestTriage(x.id)?.status==='followup':needsReview(x))).sort((a,b)=>reviewPriority(b)-reviewPriority(a)||timelineTime(b)-timelineTime(a))}
function renderReview(){const rows=reviewRows();$('reviewCount').textContent=`当前筛选 ${rows.length}条 · 排序优先关注人物、争议及重大事项`;$('reviewList').innerHTML=rows.slice(0,reviewLimit).map(x=>{const t=latestTriage(x.id);return `<article class="entry"><div class="meta"><strong>${esc(pBy(x.person)?.name)}</strong><span class="pill pending">${esc(statusNames[verification(x)])}</span><span class="pill">${esc(kindNames[x.kind]||'记录')}</span><span class="small">${esc(t?.status==='followup'?'稍后复核':t?.status==='irrelevant'?'已排除无关':t?.status==='duplicate'?'疑似重复':'未处理')}</span></div><h3>${link(x.url,x.title)}</h3><p>${esc(x.summary.slice(0,500))}</p><div class="small">${esc(freshness(x))} · 收录 ${esc(fmt(x.recordedAt))}${t?.note?'<br>队列备注：'+esc(t.note):''}</div><div class="actions">${link(x.url,'核对出处')}<button data-process="${esc(x.id)}">五步处理</button><button data-edit="${esc(x.id)}">整理／修订</button><button data-triage="${esc(x.id)}">安排复核／排除无关</button></div></article>`}).join('')||'<div class="empty">没有符合条件的待核验记录。排除只改变复核队列，原始档案仍可在时间轴查看。</div>';$('reviewMore').hidden=rows.length<=reviewLimit}
function openTriage(id){const x=byId(id),t=latestTriage(id);$('triageItem').value=id;$('triagePreview').textContent=(pBy(x.person)?.name||'')+' · '+x.title;$('triageStatus').value=t?.status||'pending';$('triageNote').value=t?.note||'';$('triageDialog').showModal()}
function briefData(day=today()){const start=new Date(day+'T12:00:00Z');start.setUTCDate(start.getUTCDate()-6);const min=start.toISOString().slice(0,10),scope=new Set(state.people.filter(matchPerson).map(p=>p.id)),rows=currentRecords().filter(x=>scope.has(x.person)&&!['irrelevant','duplicate'].includes(latestTriage(x.id)?.status)),newRows=rows.filter(x=>x.kind!=='draft'&&localDay(x.recordedAt)===day),recent=rows.filter(x=>x.kind!=='draft'&&localDay(x.statementDate||x.publishedAt)>=min&&localDay(x.statementDate||x.publishedAt)<=day).sort((a,b)=>timelineTime(b)-timelineTime(a)),fresh=newRows.filter(x=>localDay(x.statementDate||x.publishedAt)===day),backfill=newRows.filter(x=>localDay(x.statementDate||x.publishedAt)&&localDay(x.statementDate||x.publishedAt)<day),sources=state.sources.filter(s=>scope.has(s.person)&&s.enabled&&s.type!=='manual'),failed=sources.filter(s=>state.sourceStatuses[s.id]?.ok===false),success=sources.filter(s=>state.sourceStatuses[s.id]?.ok===true),due=state.scorecard.predictions.filter(p=>scope.has(p.person)&&p.dueDate<=day&&!['confirmed','unresolvable'].includes(lastSettlement(p.id)?.status));return{day,newRows,recent,fresh,backfill,unknown:newRows.length-fresh.length-backfill.length,sources,failed,success,due,checked:recent.filter(x=>['verified','source_checked'].includes(verification(x))),leads:recent.filter(x=>!['verified','source_checked'].includes(verification(x)))}}
function briefCards(rows){return rows.slice(0,20).map(x=>`<div class="brief-row"><div><span class="pill ${['verified','source_checked'].includes(verification(x))?'original':'pending'}">${esc(statusNames[verification(x)])}</span> <strong>${esc(pBy(x.person)?.name)}</strong> <span class="small">${esc(fmt(x.statementDate||x.publishedAt,true))}</span></div><p>${link(x.url,x.title)}</p><div class="small">${esc(x.source)}${x.statementDate?'':' · 本人表态日未知'}</div><div class="actions"><button data-process="${esc(x.id)}">复核／处理</button><button data-triage="${esc(x.id)}">队列标记</button></div></div>`).join('')+(rows.length>20?`<p class="small">其余${rows.length-20}条可在观点时间轴查看。</p>`:'')||'<p>暂无符合条件的材料。</p>'}
function renderBrief(){const day=$('briefDate').value||today();if(!validDate(day)||day>today()){$('briefContent').innerHTML='<div class="empty">请选择有效日期，不能晚于今天。</div>';return}const d=briefData(day);$('briefContent').innerHTML=`<div class="box"><h3>${esc(day)} · 当前人物筛选范围</h3><p>当日新增收录 <strong>${d.newRows.length}</strong>条；其中当日表态／发布 <strong>${d.fresh.length}</strong>条，历史补录 <strong>${d.backfill.length}</strong>条，材料日期未知 <strong>${d.unknown}</strong>条。</p><p>来源当前最近状态（不随日期回溯）：成功 ${d.success.length}，失败 ${d.failed.length}，未检查 ${d.sources.length-d.success.length-d.failed.length}。成功0条可能来自作者筛选，不等于发现新观点。</p><p>到期尚未完成复核的预测 ${d.due.length}条；无合格结果数据时保持缺数据。</p></div><div class="box"><h3>近7天 · 已核查出处／用户核验材料</h3>${briefCards(d.checked)}</div><div class="box"><h3>近7天 · 公开线索，尚未认证为本人观点</h3>${briefCards(d.leads)}</div><div class="box"><h3>来源失败与到期复核</h3>${d.failed.map(s=>`<p>${esc(pBy(s.person)?.name)} · ${esc(s.name)}<br>${esc(state.sourceStatuses[s.id].error)}<br><span class="small">上次成功 ${esc(fmt(state.sourceStatuses[s.id].lastSuccess))}</span></p>`).join('')||'<p>当前范围没有已记录的来源失败；未检查来源另计。</p>'}${d.due.slice(0,20).map(p=>`<p>${esc(pBy(p.person)?.name)} · ${esc(p.symbol)} · 到期 ${esc(p.dueDate)} <button data-result="${esc(p.id)}">查看／复核</button></p>`).join('')}</div>`}
function briefMarkdown(){const d=briefData($('briefDate').value||today()),clean=s=>String(s||'').replace(/[\r\n]/g,' ').replace(/[\[\]]/g,'');const lines=[`# 投资观点每日简报 · ${d.day}（北京时间）`,'',`当前人物筛选范围；生成 ${fmt(now())}。`,'收录时间不代表本人表态时间。',`当日收录 ${d.newRows.length}；当天表态／发布 ${d.fresh.length}；历史补录 ${d.backfill.length}；日期未知 ${d.unknown}。`,`来源当前最近状态：成功${d.success.length}，失败${d.failed.length}，未检查${d.sources.length-d.success.length-d.failed.length}。`,''];for(const [name,rows]of[['近7天已核查出处／用户核验材料',d.checked],['近7天公开线索（待核验）',d.leads]]){lines.push('## '+name,'');if(!rows.length)lines.push('暂无符合条件的材料。');for(const x of rows.slice(0,20))lines.push(`- ${clean(pBy(x.person)?.name)}｜${statusNames[verification(x)]}｜${localDay(x.statementDate||x.publishedAt)}｜${clean(x.title)}`,`  出处：${safeUrl(x.url)||'无'}`);if(rows.length>20)lines.push(`其余${rows.length-20}条请在时间轴查看。`);lines.push('')}lines.push('## 来源失败与到期复核','');for(const s of d.failed)lines.push(`- ${clean(pBy(s.person)?.name)}｜${clean(s.name)}｜${clean(state.sourceStatuses[s.id].error)}`);lines.push(`到期未完成复核预测 ${d.due.length}条。`,'','仅标题与来源摘要的整理；未核验线索不当作本人观点或投资建议。');return lines.join('\n')}


$('briefDate').onchange=renderBrief;$('exportBrief').onclick=()=>{if(!validDate($('briefDate').value)||$('briefDate').value>today())return toast('日期无效');download(briefMarkdown(),'daily-'+$('briefDate').value+'.md','text/markdown;charset=utf-8')};
$('reviewStatus').onchange=$('reviewFav').onchange=()=>{reviewLimit=30;renderReview()};$('reviewMore').onclick=()=>{reviewLimit+=30;renderReview()};$('reviewNext').onclick=()=>{const rows=reviewRows();if(rows.length)openProcess(rows[0].id);else toast('当前队列没有待处理记录。')};$('reviewExport').onclick=()=>download(csvEncode([['人物','标题','核验状态','队列状态','备注','来源发布','收录时间','链接','记录ID'],...reviewRows().map(x=>[pBy(x.person)?.name,x.title,verification(x),latestTriage(x.id)?.status||'pending',latestTriage(x.id)?.note,x.publishedAt,x.recordedAt,x.url,x.id])]),'review-queue-'+today()+'.csv','text/csv;charset=utf-8');
$('triageForm').onsubmit=e=>{e.preventDefault();const id=$('triageItem').value,status=$('triageStatus').value,note=$('triageNote').value.trim();if(!byId(id))return toast('记录不存在。');if(['irrelevant','duplicate'].includes(status)&&!note)return toast('请记录排除无关／疑似重复的具体原因。');state.triage.push({id:uid('triage'),itemId:id,status,note,recordedAt:now(),previous:latestTriage(id)?.id||null});persist();$('triageDialog').close();render();toast('队列标记已追加，原始记录保留。')};

loadSettings();$('briefDate').value=today();$('briefDate').max=today();render();schedule();if(state.migrationNote)toast(state.migrationNote);if(state.settings.mode!=='offline')setTimeout(async()=>{if(await detectLocal()){try{await syncFiles()}catch(e){$('status').textContent=e.message}}if(state.settings.autoStart&&!busy)refresh(state.favorites)},600);
